function crash(reason){if(state.crashed)return;state.crashed=true;state.running=false;explosionSound();$('#explosionFlash').classList.add('show');const blast=new THREE.Group(),particles=[];for(let i=0;i<70;i++){const p=new THREE.Mesh(new THREE.SphereGeometry(.6+Math.random()*2.4,7,5),new THREE.MeshBasicMaterial({color:i%3===0?0x2b2420:i%2?0xff4a00:0xffc21c,transparent:true}));p.position.set((Math.random()-.5)*6,(Math.random()-.2)*5,(Math.random()-.5)*6);p.userData.velocity=new THREE.Vector3((Math.random()-.5)*44,8+Math.random()*38,(Math.random()-.5)*44);blast.add(p);particles.push(p)}blast.position.copy(aircraft.position);scene.add(blast);const flash=new THREE.PointLight(0xff4b00,65,700);flash.position.copy(aircraft.position);scene.add(flash);aircraft.visible=false;let life=0;const animateBlast=()=>{life+=.025;particles.forEach(p=>{p.position.addScaledVector(p.userData.velocity,.025);p.userData.velocity.y-=.75;p.material.opacity=Math.max(0,1-life/2.2);p.scale.multiplyScalar(1.012)});flash.intensity=Math.max(0,65-life*45);if(life<2.3)requestAnimationFrame(animateBlast);else{scene.remove(blast,flash)}};animateBlast();setTimeout(()=>{$('#crashReason').textContent=reason;ui.crash.classList.add('show')},650)}
function updateWorld(dt){for(const t of traffic){if(t.mode===0){t.model.rotation.y=0;t.z-=t.speed*dt;if(t.z<-3800)t.z=2100;t.y=2.8}else if(t.mode===1){t.model.rotation.y=0;t.z-=t.speed*dt;t.y=2.8+Math.min(1000,(1800-t.z)*.13);if(t.z<-12000){t.z=1800;t.y=2.8}}else{t.model.rotation.y=Math.PI;t.z+=t.speed*dt;t.y=t.z<-3600?2.8+(-3600-t.z)*.107:2.8;if(t.z>1800){t.z=-12000;t.y=902}}t.model.position.set(t.x,t.y,t.z);const d=Math.hypot(state.x-t.x,state.y-t.y,state.z-t.z);if(d<160&&!state.onGround&&performance.now()-collisionWarningTimer>2600){toast('TRAFFIC · 前方飞机接近');warningTone();collisionWarningTimer=performance.now()}if(d<22)crash('与其他飞机相撞，飞行结束')}for(const b of birds){b.model.position.x+=Math.sin(performance.now()/1800+b.phase)*b.speed*dt;b.model.position.z-=b.speed*dt;b.model.rotation.y+=dt*.3;if(b.model.position.z<-15000)b.model.position.z=2500;const d=Math.hypot(state.x-b.model.position.x,state.y-b.model.position.y,state.z-b.model.position.z);if(d<85&&performance.now()-collisionWarningTimer>2200){toast('BIRD · 鸟群接近');warningTone();collisionWarningTimer=performance.now()}if(d<10)crash('发生鸟击，飞行结束')}const tileSize=3600,cx=Math.round(state.x/tileSize),cz=Math.round(state.z/tileSize);terrainTiles.forEach((tile,i)=>{tile.position.x=(cx+(i%4)-1.5)*tileSize;tile.position.z=(cz+Math.floor(i/4)-1.5)*tileSize});for(const cloud of scene.children.filter(o=>o.type==='Group'&&o!==aircraft&&o.children.some(c=>c.geometry===cloudGeo))){if(Math.abs(cloud.position.z-state.z)>13000)cloud.position.z=state.z-9000-Math.random()*4000}}

function toast(message){ui.toast.textContent=message;ui.toast.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>ui.toast.classList.remove('show'),2200)}
function initAudio(){if(audio)return;audio=new(window.AudioContext||window.webkitAudioContext)();engineOsc=audio.createOscillator();const rumble=audio.createOscillator(),filter=audio.createBiquadFilter(),compressor=audio.createDynamicsCompressor();engineGain=audio.createGain();engineOsc.type='sawtooth';engineOsc.frequency.value=54;rumble.type='sine';rumble.frequency.value=31;filter.type='lowpass';filter.frequency.value=260;engineGain.gain.value=0;engineOsc.connect(filter);rumble.connect(filter);filter.connect(engineGain).connect(compressor).connect(audio.destination);engineOsc.start();rumble.start();const noiseBuffer=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),d=noiseBuffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;const noise=audio.createBufferSource(),noiseFilter=audio.createBiquadFilter();engineNoiseGain=audio.createGain();noise.buffer=noiseBuffer;noise.loop=true;noiseFilter.type='bandpass';noiseFilter.frequency.value=420;noiseFilter.Q.value=.55;engineNoiseGain.gain.value=0;noise.connect(noiseFilter).connect(engineNoiseGain).connect(compressor);noise.start()}
function beep(freq=740,duration=.12){if(!state.sound)return;initAudio();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration)}
function powered(){return state.battery||state.groundPower||state.apuGen||state.engines.some(n=>n>55)}
function toggleSystem(name,button){state[name]=!state[name];button.classList.toggle('on',state[name]);button.textContent=button.textContent.replace(/ ON| OFF/g,'')+(state[name]?' ON':' OFF');if(name==='apuMaster'&&!state.apuMaster){state.apuRunning=false;state.apuGen=false}refreshChecklist();beep(520,.05)}
function startAPU(){if(!state.battery||!state.apuMaster||!state.fuelPumps){toast('APU START 需要 BATTERY、APU MASTER 和 FUEL PUMPS');return}if(state.apuRunning)return;toast('APU 正在启动…');const b=$('[data-action="apuStart"]');b.classList.add('start');setTimeout(()=>{state.apuRunning=true;b.classList.remove('start');b.classList.add('on');b.textContent='APU RUNNING';toast('APU 可用');beep(880,.18);refreshChecklist()},3200)}
function startEngine(index){if(!state.apuRunning||!state.bleed||!state.fuelPumps){toast('发动机启动需要 APU RUNNING、APU BLEED 和 FUEL PUMPS');return}if(state.engineStarting[index]||state.engines[index]>50)return;state.engineStarting[index]=true;toast(`ENGINE ${index+1} START`);const timer=setInterval(()=>{state.engines[index]=Math.min(64,state.engines[index]+3);if(state.engines[index]>=60){clearInterval(timer);state.engineStarting[index]=false;state.engines[index]=60;toast(`ENGINE ${index+1} STABLE`);beep(940,.13);refreshChecklist()}},140)}
function setReady(){Object.assign(state,{battery:true,groundPower:false,apuMaster:true,apuRunning:true,apuGen:true,fuelPumps:true,hydraulics:true,packs:true,bleed:true,beacon:true,engines:[60,60],flaps:2,ready:true});ui.flaps.value=2;$('#flapsVal').textContent='5';$$('[data-switch]').forEach(b=>{const n=b.dataset.switch;b.classList.toggle('on',!!state[n])});$('[data-action="apuStart"]').classList.add('on');$('[data-action="apuStart"]').textContent='APU RUNNING';refreshChecklist()}
function refreshChecklist(){const values={battery:state.battery,ground:state.groundPower||state.apuGen||state.engines.some(n=>n>55),apu:state.apuRunning,fuel:state.fuelPumps,engines:state.engines.every(n=>n>55),hydraulics:state.hydraulics};$$('.check').forEach(row=>{const ok=values[row.dataset.check];row.classList.toggle('done',ok);row.querySelector('b').textContent=ok?'ON':'OFF'})}
async function enterFullscreen(){if(document.fullscreenElement)return;try{await document.documentElement.requestFullscreen()}catch{toast('浏览器阻止了自动全屏，请点击右上角“全屏”')}}
function begin(quick){initAudio();state.running=true;ui.start.classList.add('hidden');enterFullscreen();if(quick)setReady();toast(quick?'飞机已在跑道就绪':'从顶板开始：BATTERY → GROUND POWER → APU');}

const tutorialSteps=[
  {title:'打开顶板',text:'737 的冷舱启动从头顶面板开始。这里负责电源、燃油、引气、液压和灯光。',target:'#overheadBtn',done:()=>ui.overhead.classList.contains('open'),prepare:()=>ui.overhead.classList.remove('open')},
  {title:'接通电瓶',text:'点击 BATTERY。电瓶为基础控制和备用系统供电，是冷舱启动的第一步。',target:'[data-switch="battery"]',done:()=>state.battery},
  {title:'接通地面电源',text:'点击 GROUND POWER，让飞机在发动机未启动时获得稳定交流电。仪表随后会点亮。',target:'[data-switch="groundPower"]',done:()=>state.groundPower},
  {title:'开启燃油泵',text:'点击 FUEL PUMPS。APU 和发动机启动前必须保证燃油供应。',target:'[data-switch="fuelPumps"]',done:()=>state.fuelPumps},
  {title:'启动 APU',text:'先打开 APU MASTER，再点击 APU START。等待约 3 秒，按钮显示 APU RUNNING。',target:'[data-switch="apuMaster"]',done:()=>state.apuRunning},
  {title:'建立引气',text:'APU 运转后点击 APU BLEED。引气提供发动机启动所需的压缩空气。',target:'[data-switch="bleed"]',done:()=>state.bleed},
  {title:'启动双发',text:'依次点击 ENGINE 1 和 ENGINE 2，等待两台发动机稳定到 60%。',target:'[data-action="startEng1"]',done:()=>state.engines.every(n=>n>55)},
  {title:'接通液压',text:'点击 HYD PUMPS。没有液压，主要飞行操纵面无法正常工作。',target:'[data-switch="hydraulics"]',done:()=>state.hydraulics},
  {title:'设置起飞襟翼',text:'把右下角 FLAPS 拉到 5。襟翼增加低速升力，缩短起飞距离。',target:'#flaps',done:()=>state.flaps>=2,prepare:()=>ui.overhead.classList.remove('open')},
  {title:'看懂 ND 雷达',text:'底部白色飞机是自己；白色轮廓是跑道；紫线是航路，紫色菱形是活动航点；黄色方块是其他飞机，红点是鸟群，棕色三角是山体或建筑。GS 是地速，TRK 是航迹，RANGE 5 NM 表示显示前方约 5 海里。',target:'#ndPanel',done:()=>true,prepare:()=>ui.overhead.classList.remove('open')},
  {title:'起飞',text:'把 THRUST 推到 TO/GA，Q 向左、E 向右保持跑道方向。速度达到 100 节后按一下 W 发出拉起指令，飞机会缓慢抬起前轮，并在约 112–120 节平顺离地。离地后会自动保持约 10° 爬升；正上升后按 G 收起落架。',target:'#throttle',done:()=>state.airborne&&state.altitude>100},
  {title:'保持爬升姿态',text:'把机头保持在约 10–15°，不要持续拉到垂直。观察 PFD 右侧高度和 V/S，保持稳定正上升。',target:'#pfdPanel',done:()=>state.altitude>1500},
  {title:'爬升到安全高度',text:'继续爬升到 10,000 英尺（约 3,000 米）。途中注意 ND 上的其他飞机、鸟群和山体目标，必要时转弯避让。',target:'#ndPanel',done:()=>state.altitude>=10000}
];
const closePopups=()=>{ui.overhead.classList.remove('open');ui.cdu.classList.remove('open')};
const panelTutorialSteps=[
  {title:'欢迎来到 737-800 驾驶舱',text:'这次导览只讲面板，不要求你操作。高亮区域就是当前讲解对象；看完后点击“下一步”。',target:'#mainPanel',prepare:closePopups},
  {title:'MCP 模式控制面板',text:'MCP 用来选择自动驾驶的速度、航向和高度。IAS、HDG、ALTITUDE 是目标值；LNAV/VNAV 管理航路与垂直剖面，CMD A 接通自动驾驶。',target:'#mcpPanel',prepare:closePopups},
  {title:'PFD 主飞行显示器',text:'左侧数字是飞机速度 IAS，单位是节（KT）；右侧是高度。中央蓝棕地平仪显示俯仰和滚转，顶部绿色文字显示自动飞行模式。',target:'#pfdPanel',prepare:closePopups},
  {title:'ND 导航与防撞显示',text:'白色飞机符号是自己；白色轮廓是跑道；紫线和菱形是航路与活动航点；黄色方块是其他飞机，红点是鸟群，棕色三角是山体或建筑。GS 是地速，TRK 是航迹。',target:'#ndPanel',prepare:closePopups},
  {title:'发动机显示',text:'这里的大数字约 60 或 61 是发动机 N1 转速百分比，不是飞机速度。真正速度请看左侧 PFD 的 IAS。下面还能看到 EGT、燃油、襟翼和起落架状态。',target:'#eicasPanel',prepare:closePopups},
  {title:'警告系统',text:'FIRE WARN 是火警，MASTER CAUTION 是主警戒。亮起时先识别故障来源，再处理对应系统；它们不是普通状态灯。',target:'#warningsPanel',prepare:closePopups},
  {title:'驾驶盘 Yoke',text:'空中按 W 抬头、S 压低机头，A/D 控制滚转。地面低于 100 节时 W/S 和 A/D 锁定；达到 100 节后 W 解锁用于起飞拉起。地面 Q 向左转，E 向右转。',target:'#yokePanel',prepare:closePopups},
  {title:'中央操纵区',text:'SPD BRK 是减速板，THRUST 是油门，FLAPS 是襟翼，GEAR 控制起落架。起飞常用襟翼 5、油门 TO/GA，离地并确认正上升后收轮。',target:'#controlsPanel',prepare:closePopups},
  {title:'Overhead 顶板',text:'顶板管理电源、APU、燃油、引气、液压和灯光。冷舱启动大多从这里开始；关闭关键系统会直接影响仪表和飞机状态。',target:'#overhead',prepare:()=>{ui.cdu.classList.remove('open');ui.overhead.classList.add('open')}},
  {title:'CDU / FMC',text:'CDU 用来输入起点、终点和航路点。点击 EXECUTE ROUTE 后航路写入 ND，并预位 LNAV。后续版本会继续加入 SID、STAR、性能页和进近。',target:'#cdu',prepare:()=>{ui.overhead.classList.remove('open');ui.cdu.classList.add('open')}},
  {title:'导览完成',text:'现在你已经知道速度在哪里看，也能分清 MCP、飞行仪表、发动机屏、中央操纵区、顶板和 CDU。接下来建议打开“启动教学”完成一次冷舱启动。',target:'#tutorialBtn',prepare:closePopups}
];
function activeTutorialSteps(){return tutorialKind==='panels'?panelTutorialSteps:tutorialSteps}
function clearTutorialTarget(){$$('.tutorial-target').forEach(e=>e.classList.remove('tutorial-target'))}
function placeTutorial(target){const card=$('#tutorial');card.style.top='';card.style.bottom='';card.style.left='50%';card.style.right='auto';card.style.transform='translateX(-50%)';if(!target)return;const r=target.getBoundingClientRect();if(r.top<innerHeight*.5){card.style.top='auto';card.style.bottom='18px'}else{card.style.top='75px';card.style.bottom='auto'}if(innerWidth>900&&r.left<innerWidth*.38){card.style.left='auto';card.style.right='18px';card.style.transform='none'}else if(innerWidth>900&&r.right>innerWidth*.62){card.style.left='18px';card.style.right='auto';card.style.transform='none'}}
function showTutorialStep(){clearTutorialTarget();const steps=activeTutorialSteps(),step=steps[tutorialIndex];if(!step){finishTutorial();return}step.prepare?.();const informational=tutorialKind==='panels';$('#tutorialProgress').textContent=`${informational?'驾驶舱面板导览':'冷舱启动教学'} ${tutorialIndex+1} / ${steps.length}`;$('#tutorialTitle').textContent=step.title;$('#tutorialText').textContent=step.text;$('#tutorialBack').disabled=tutorialIndex===0;$('#tutorialNext').classList.toggle('active',informational||step.done());$('#tutorialNext').textContent=tutorialIndex===steps.length-1?'完成':'下一步';const target=$(step.target);target?.classList.add('tutorial-target');placeTutorial(target);$('#tutorialHint').textContent=informational?'阅读后点击下一步':step.done()?'已完成 ✓':'等待你完成操作…'}
function beginTutorial(kind){tutorialKind=kind;if(!state.running)begin(kind==='panels');tutorialActive=true;tutorialIndex=0;$('#tutorial').classList.remove('hidden');document.body.classList.remove('view-external');state.external=false;showTutorialStep()}
function startTutorial(){beginTutorial('startup')}
function startPanelTour(){beginTutorial('panels')}
function finishTutorial(){const panels=tutorialKind==='panels';tutorialActive=false;clearTutorialTarget();closePopups();$('#tutorial').classList.add('hidden');toast(panels?'驾驶舱面板导览完成！':'冷舱启动教学完成！');localStorage.setItem(panels?'b738-panel-tour-complete':'b738-tutorial-complete','1')}
function monitorTutorial(){if(!tutorialActive||tutorialKind==='panels')return;const step=activeTutorialSteps()[tutorialIndex];if(step?.done()){$('#tutorialHint').textContent='已完成 ✓';$('#tutorialNext').classList.add('active')}}

$$('[data-switch]').forEach(b=>b.addEventListener('click',()=>toggleSystem(b.dataset.switch,b)));$('[data-action="apuStart"]').onclick=startAPU;$('[data-action="startEng1"]').onclick=()=>startEngine(0);$('[data-action="startEng2"]').onclick=()=>startEngine(1);
$('#panelTourStart').onclick=startPanelTour;$('#tutorialStart').onclick=startTutorial;$('#coldStart').onclick=()=>begin(false);$('#quickStart').onclick=()=>begin(true);$('#overheadBtn').onclick=()=>ui.overhead.classList.toggle('open');$('#cduBtn').onclick=()=>ui.cdu.classList.toggle('open');
$('#panelTourBtn').onclick=startPanelTour;$('#tutorialBtn').onclick=startTutorial;$('#tutorialClose').onclick=()=>{tutorialActive=false;clearTutorialTarget();closePopups();$('#tutorial').classList.add('hidden')};$('#tutorialBack').onclick=()=>{tutorialIndex=Math.max(0,tutorialIndex-1);showTutorialStep()};$('#tutorialNext').onclick=()=>{const step=activeTutorialSteps()[tutorialIndex];if(step.done&&!step.done()){toast('请先完成当前教学操作');return}tutorialIndex++;showTutorialStep()};
$('#fullscreenBtn').onclick=()=>document.fullscreenElement?document.exitFullscreen():enterFullscreen();document.addEventListener('fullscreenchange',()=>{$('#fullscreenBtn').textContent=document.fullscreenElement?'退出全屏':'全屏'});
$('#viewBtn').onclick=()=>{state.external=!state.external;document.body.classList.toggle('view-external',state.external);$('#viewBtn').textContent=state.external?'驾驶舱视角':'外部视角'};
$('#restartBtn').onclick=()=>location.reload();
ui.sound.onclick=()=>{state.sound=!state.sound;ui.sound.textContent=`声音 ${state.sound?'ON':'OFF'}`;ui.sound.classList.toggle('active',state.sound);if(engineGain&&!state.sound)engineGain.gain.value=0};
ui.throttle.oninput=()=>{state.throttle=+ui.throttle.value;$('#throttleVal').textContent=state.throttle>90?'TO/GA':state.throttle+'%'};ui.flaps.oninput=()=>{state.flaps=+ui.flaps.value;$('#flapsVal').textContent=state.flaps?['','1','5','15','30','40'][state.flaps]:'UP'};ui.speedbrake.oninput=()=>{state.speedbrake=+ui.speedbrake.value;$('#speedbrakeVal').textContent=state.speedbrake>75?'UP':state.speedbrake?'ARMED':'DOWN'};ui.gear.onclick=()=>{if(state.onGround&&state.gearDown){state.gearWarnUntil=performance.now()+2600;toast('GEAR LEVER LOCKED · 地面禁止收轮');beep(245,.65);return}if(state.gearDamaged){toast('GEAR JAMMED · 起落架损坏，无法收起');warningTone();return}if(!state.gearDown&&state.ias>270){state.gearWarnUntil=performance.now()+2600;toast('VLO EXCEEDED · 速度过高，禁止放轮');warningTone();return}state.gearDown=!state.gearDown;ui.gear.classList.toggle('down',state.gearDown);ui.gear.innerHTML=`GEAR<br>${state.gearDown?'DOWN':'UP'}`;beep(430,.12)};
$$('[data-ap]').forEach(b=>b.onclick=()=>{const n=b.dataset.ap;if(n==='ap'&&!state.engines.every(v=>v>50)){toast('CMD A 不可用：发动机未运行');return}state.ap[n]=!state.ap[n];syncApButtons();beep(state.ap[n]?900:480,.08)});
['mcpSpeed','mcpHeading','mcpAltitude'].forEach(id=>$('#'+id).onchange=()=>{const k=id.replace('mcp','').toLowerCase();state.targets[k]=+$('#'+id).value});
const waypointMap={PEK:[0,-2200],ANDAN:[600,-3800],OLNEX:[-500,-5600],SASAN:[0,-7600]};
$('#execRoute').onclick=()=>{const names=$('#route').value.toUpperCase().split(',').map(v=>v.trim()).filter(Boolean);state.route=names.map((name,i)=>({name,pos:waypointMap[name]||[(i%2?1:-1)*500,-2200-i*1600]}));state.activeLeg=0;$('#legs').textContent=`${$('#origin').value.toUpperCase()} → ${names.join(' → ')} → ${$('#destination').value.toUpperCase()}\nACTIVATE / EXECUTED`;state.ap.lnav=true;$('[data-ap="lnav"]').classList.add('on');toast('航路已执行，LNAV ARM');beep(1000,.12)};

function syncApButtons(){$$('[data-ap]').forEach(b=>b.classList.toggle('on',!!state.ap[b.dataset.ap]));$('#externalAt').classList.toggle('on',state.ap.at);$('#externalCmd').classList.toggle('on',state.ap.ap);$('#externalHdg').classList.toggle('on',state.ap.heading)}
function selectedAirport(){return airports.find(a=>a.code===$('#airportSelect').value)||airports[0]}
function updateRunwayChoices(){const ap=selectedAirport(),select=$('#runwaySelect');select.innerHTML=ap.runways.map(r=>`<option value="${r.id}">跑道 ${r.id} · 航向 ${String(r.heading).padStart(3,'0')}°</option>`).join('');$('#externalApStatus').textContent=`${ap.name} · ${ap.code} · ${ap.runways.length} 条可用跑道`}
