function drawExternalHUD(){if(!state.external)return;$('#hudSpeed').textContent=`${Math.round(state.ias)} KT`;$('#hudAltitude').textContent=`${Math.round(state.altitude)} FT`;$('#hudVs').textContent=`${Math.round(state.vs)} FPM`;const{x,w,h}=fitCanvas(ui.externalRadar);x.fillStyle='#020607';x.fillRect(0,0,w,h);const cx=w/2,cy=h*.82,range=6000,scale=Math.min(w*.46,h*.75)/range,angle=-state.heading*Math.PI/180,project=(px,pz)=>{const dx=px-state.x,dz=pz-state.z;return[cx+(dx*Math.cos(angle)-dz*Math.sin(angle))*scale,cy+(dx*Math.sin(angle)+dz*Math.cos(angle))*scale]};x.strokeStyle='#31514f';for(const f of[.33,.66,1]){x.beginPath();x.arc(cx,cy,range*scale*f,Math.PI,Math.PI*2);x.stroke()}for(const t of traffic){const p=project(t.x,t.z);if(p[0]>4&&p[0]<w-4&&p[1]>4&&p[1]<h){x.fillStyle='#ffb836';x.fillRect(p[0]-3,p[1]-3,6,6)}}for(const b of birds){const p=project(b.model.position.x,b.model.position.z);if(p[0]>4&&p[0]<w-4&&p[1]>4&&p[1]<h){x.fillStyle='#ff4d3d';x.beginPath();x.arc(p[0],p[1],2,0,Math.PI*2);x.fill()}}for(const o of obstacles){const p=project(o.x,o.z);if(p[0]>4&&p[0]<w-4&&p[1]>4&&p[1]<h){x.strokeStyle='#b58a67';x.beginPath();x.moveTo(p[0],p[1]-5);x.lineTo(p[0]-5,p[1]+4);x.lineTo(p[0]+5,p[1]+4);x.closePath();x.stroke()}}x.strokeStyle='#fff';x.beginPath();x.moveTo(cx,cy-8);x.lineTo(cx-5,cy+7);x.lineTo(cx+5,cy+7);x.closePath();x.stroke();x.fillStyle='#92a9b1';x.font='9px Consolas';x.fillText('黄:飞机  红:鸟群  △:山/建筑',6,11)}
function drawEICAS(){const{x,w,h}=fitCanvas(ui.eicas);x.fillStyle='#020505';x.fillRect(0,0,w,h);if(!powered()){x.fillStyle='#ff8b25';x.font='11px Consolas';x.fillText('ENG DISPLAY',w/2-38,h/2);return}x.fillStyle='#fff';x.font='10px Consolas';x.fillText('N1',w/2-7,15);state.engines.forEach((base,i)=>{const n=base?Math.min(101,22+state.throttle*.78):0,cx=i?w*.72:w*.28,cy=55,r=27;x.strokeStyle='#55615c';x.lineWidth=4;x.beginPath();x.arc(cx,cy,r,.7*Math.PI,2.3*Math.PI);x.stroke();x.strokeStyle=n>95?'#ff4d3d':'#72e57b';x.beginPath();x.arc(cx,cy,r,.7*Math.PI,(.7+1.6*n/100)*Math.PI);x.stroke();x.fillStyle='#fff';x.font='bold 13px Consolas';x.fillText(n.toFixed(1),cx-18,cy+5);x.fillStyle='#72e57b';x.font='10px Consolas';x.fillText(`EGT ${Math.round(n*7.4)}`,cx-23,105)});x.fillStyle='#fff';x.fillText(`FUEL ${Math.round(state.fuel)} KG`,12,h-22);x.fillText(`FLAPS ${state.flaps?['','1','5','15','30','40'][state.flaps]:'UP'}`,12,h-8);x.fillText(`GEAR ${state.gearDown?'DOWN':'UP'}`,w-72,h-8)}
function updateWarnings(){const stall=state.airborne&&state.ias<105&&Math.abs(state.pitch)>24,gearAlert=state.gearPosition>.15&&state.ias>270,caution=state.running&&(!powered()||state.engines.some(n=>state.ready&&n<20)||(!state.hydraulics&&state.engines.some(n=>n>50))||performance.now()<state.gearWarnUntil||stall||gearAlert||state.gearDamaged);$('#masterCaution').classList.toggle('lit',caution);$('#fireWarn').classList.toggle('lit',state.engines.some(n=>n>103))}
function renderView(){const heading=state.heading*Math.PI/180,pitch=state.pitch*Math.PI/180,viewHeading=heading+lookYaw,viewPitch=THREE.MathUtils.clamp(pitch-lookPitch,-1.35,1.35),forward=new THREE.Vector3(Math.sin(viewHeading)*Math.cos(viewPitch),Math.sin(viewPitch),-Math.cos(viewHeading)*Math.cos(viewPitch));if(state.external){camera.fov=68;const target=new THREE.Vector3(state.x,state.y+1.2,state.z),distance=state.onGround?Math.min(orbitDistance,72):orbitDistance,offset=new THREE.Vector3(-Math.sin(viewHeading)*Math.cos(lookPitch)*distance,Math.sin(lookPitch)*distance+Math.max(16,distance*.3),Math.cos(viewHeading)*Math.cos(lookPitch)*distance);camera.position.lerp(target.clone().add(offset),.12);const noseAim=new THREE.Vector3(Math.sin(heading)*Math.cos(pitch),Math.sin(pitch),-Math.cos(heading)*Math.cos(pitch)).multiplyScalar(18);camera.up.set(0,1,0);camera.lookAt(target.clone().add(noseAim))}else{camera.fov=78;camera.position.set(state.x,state.y+2.45,state.z-1.25);camera.up.set(Math.sin(state.roll*Math.PI/180),Math.cos(state.roll*Math.PI/180),0);camera.lookAt(camera.position.clone().add(forward.multiplyScalar(500)))}camera.updateProjectionMatrix();aircraft.visible=state.external&&!state.crashed;renderer.render(scene,camera)}
function loop(now){requestAnimationFrame(loop);const dt=Math.min(.04,(now-last)/1000);last=now;if(state.running){flightPhysics(dt);updateWorld(dt)}updateGearAnimation(dt);state.radioAlt=state.altitude;drawPFD();drawND();drawEICAS();drawExternalHUD();updateWarnings();monitorTutorial();renderView()}requestAnimationFrame(loop);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);if(tutorialActive)placeTutorial($(activeTutorialSteps()[tutorialIndex]?.target))});refreshChecklist();
